            lambda x: x[n // 2] ^ any(x[i] == 1 for i in range(n) if i != n // 2),  # XOR_n
            lambda x: sum(x[:n // 2]) >= n // 2,  # MAJ_n
            lambda x: all(x[i] == 0 for i in range(n - n // 2)) or any(x[i] == 1 for i in range(n - n // 2)),  # Th_{⌈n/2⌉}^n
